"validated":true},{"table":"xpert_project_pipeline_task_link","name":"FK_8f251699d90fad1516ca76d7ce7","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_task_link","name":"FK_994374211807021f593fc9c56ff","definition":"FOREIGN KEY (\"projectId\") REFERENCES xpert_project(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_task_link","name":"FK_c4d3c16a269a093b11296fb4f1b","definition":"FOREIGN KEY (\"createdById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_pipeline_task_link","name":"pipeline_task_link_node_scope_fk","definition":"FOREIGN KEY (\"nodeInstanceId\", \"projectId\") REFERENCES xpert_project_pipeline_node(id, \"projectId\") ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_task_link","name":"pipeline_task_link_project_fk","definition":"FOREIGN KEY (\"projectId\") REFERENCES xpert_project(id) ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_task_link","name":"pipeline_task_link_task_scope_fk","definition":"FOREIGN KEY (\"taskId\", \"projectId\") REFERENCES xpert_project_task(id, \"projectId\") ON DELETE CASCADE","validated":true},{"table":"xpert_project_task","name":"FK_6d852c7c806c31e758dbddd6324","definition":"FOREIGN KEY (\"createdById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_task","name":"FK_9d9cf8b6c34bd80b3eb420fa95a","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_task","name":"FK_b80de03588d26edae9b8c161d66","definition":"FOREIGN KEY (\"updatedById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_task","name":"FK_c35f6369db6cff9589d5bc6547d","definition":"FOREIGN KEY (\"projectId\") REFERENCES xpert_project(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_task","name":"pipeline_task_instance_fk","definition":"FOREIGN KEY (\"pipelineInstanceId\", \"projectId\") REFERENCES xpert_project_pipeline_instance(id, \"projectId\") ON DELETE CASCADE","validated":true},{"table":"xpert_project_task_execution","name":"FK_80d732f70e6fe7ea1926b04189b","definition":"FOREIGN KEY (\"projectId\") REFERENCES xpert_project(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_task_execution","name":"FK_963bae8181a97692c77e1cd0559","definition":"FOREIGN KEY (\"updatedById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_task_execution","name":"FK_9dab367d0158081583f38fddbf3","definition":"FOREIGN KEY (\"taskId\") REFERENCES xpert_project_task(id) ON DELETE CASCADE","validated":true},{"table":"xpert_project_task_execution","name":"FK_f9676efc80b83a8878c3477690c","definition":"FOREIGN KEY (\"conversationId\") REFERENCES chat_conversation(id) ON DELETE SET NULL","validated":true},{"table":"xpert_project_task_execution","name":"FK_fc87c42b119a6ae0eeaaf095fb7","definition":"FOREIGN KEY (\"tenantId\") REFERENCES tenant(id) ON DELETE CASCADE","validated":true},{"table":"xpert_task_execution","name":"FK_841e16f3ce835913bd739c6cb01","definition":"FOREIGN KEY (\"createdById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_task_execution","name":"FK_b5e00ff54a7231e5dc71487bee3","definition":"FOREIGN KEY (\"tenantId\") REFERENCES tenant(id) ON DELETE CASCADE","validated":true},{"table":"xpert_task_execution","name":"FK_f30d419749bdfce78396ecef498","definition":"FOREIGN KEY (\"updatedById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true}],"indexes":[]}$catalog$::jsonb AS catalog),
columns AS (
  SELECT c.relname AS "table", a.attname AS name, format_type(a.atttypid,a.atttypmod) AS type,
    a.attnotnull AS "notNull", pg_get_expr(d.adbin,d.adrelid) AS "default"
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
  WHERE n.nspname=current_schema() AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
),
constraints AS (
  SELECT t.relname AS "table", c.conname AS name, pg_get_constraintdef(c.oid) AS definition,
    c.convalidated AS validated FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
),
indexes AS (
  SELECT t.relname AS "table", c.relname AS name, pg_get_indexdef(i.indexrelid) AS definition, i.indisvalid AS valid
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
)
SELECT 'column:'||e."table"||'.'||e.name AS missing FROM expected,
  jsonb_to_recordset(catalog->'columns') AS e("table" text,name text,type text,"notNull" boolean,"default" text)
WHERE NOT EXISTS (SELECT 1 FROM columns a WHERE a."table"=e."table" AND a.name=e.name AND a.type=e.type
  AND a."notNull"=e."notNull" AND a."default" IS NOT DISTINCT FROM e."default")
UNION ALL
SELECT 'constraint:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'constraints') AS e("table" text,name text,definition text,validated boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM constraints a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.validated=e.validated)
UNION ALL
SELECT 'index:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'indexes') AS e("table" text,name text,definition text,valid boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM indexes a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.valid=e.valid);
